namespace Warehouse;

public sealed class InventoryTracker
{
    private const int ReorderThreshold = 10;
    private readonly Dictionary<string, int> _stock = new();

    public int GetStockLevel(string sku)
    {
        ArgumentNullException.ThrowIfNull(sku);
        return _stock.TryGetValue(sku, out var level) ? level : 0;
    }

    public void AddStock(string sku, int quantity)
    {
        ArgumentNullException.ThrowIfNull(sku);
        ArgumentOutOfRangeException.ThrowIfLessThanOrEqual(quantity, 0);

        if (_stock.ContainsKey(sku))
            _stock[sku] += quantity;
        else
            _stock[sku] = quantity;
    }

    public bool NeedsReorder(string sku)
    {
        ArgumentNullException.ThrowIfNull(sku);
        return GetStockLevel(sku) < ReorderThreshold;
    }
}

